#ifndef MCRF_PRIVATE_SOCKS_PROFILE_H
#define MCRF_PRIVATE_SOCKS_PROFILE_H
#include <stddef.h>
#include <string.h>
/* Mechanical admission for the authenticated loopback ingress generated by
 * the host's owned helper. Ordinary empty/short-auth loopback URLs still fail.
 * Actual process, listener and generation ownership remain host requirements. */
static int mcrf_private_socks_token(const char *value) {
    if (!value) return 0;
    size_t n=0;
    for (; n<=64 && value[n]; ++n) {
        unsigned char c=(unsigned char)value[n];
        if (!((c>='0'&&c<='9')||(c>='a'&&c<='f')||c=='-')) return 0;
    }
    return n>=32 && n<=64;
}
static int mcrf_private_socks_profile(const char *host,unsigned port,unsigned version,const char *user,const char *pass) {
    return host && !strcmp(host,"127.0.0.1") && port>=1024 && port<=65535 && version==5
        && mcrf_private_socks_token(user) && mcrf_private_socks_token(pass);
}
#endif
